def value_chain(*args):
    scalar_types = (str, bytes)
    for value in args:
        if isinstance(value, scalar_types):
            yield value
            continue
        try:
            if isinstance(value, (list, tuple, set)):
                for item in value:
                    yield item
            else:
                yield from value
        except TypeError:
            yield value
```

